<?php require_once __DIR__ . '/includes/db.php'; require_once __DIR__ . '/includes/functions.php'; $st=db()->prepare("SELECT * FROM stories WHERE slug=? AND status='published'"); $st->execute([$_GET['slug']??'']); $s=$st->fetch(); if(!$s) die('Story not found.'); ?><!doctype html><html><head><meta charset="utf-8"><link rel="stylesheet" href="assets/css/style.css"><title><?=h($s['title'])?></title></head><body><section class="section" style="max-width:850px;margin:auto"><a href="index.php">← Home</a><h1><?=h($s['title'])?></h1><p><b><?=h($s['artist_name'])?></b></p><?php if($s['featured_image']): ?><img style="width:100%;border-radius:14px" src="<?=h($s['featured_image'])?>"><?php endif; ?><p><?=nl2br(h($s['body']))?></p></section></body></html>
